from taf.gnb.oam.coam.vdu.utilities.http_client import HttpClient


class TRSv1HttpClient(HttpClient):
    """ This class provides a client for the TRS v1 API. """
    def __init__(self, base_url, connection_alias):
        super(TRSv1HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/trs/v1"

    def get_external_interfaces_of_pmtu_discovery(self, timeout=30):
        endpoint = '/interfaces/external'
        headers = {
            "accept": "application/json"
        }
        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def delete_certificates_by_id(self, certificate_id, timeout=30):
        endpoint = f'/operator/certificates/{certificate_id}'
        headers = {
            "Content-Type": "application/json"
        }
        return self._send_delete_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def start_ip_connectivity_test(self, destination_ip, payload_size, dscp, source_interface_name, source_ip,
                                   timeout=30):
        endpoint = '/test/ip-connectivity'
        headers = {
            "accept": "application/json"
        }
        payload = {
            "name": source_interface_name,
            "sourceIp": source_ip,
            "destinationIp": destination_ip,
            "payloadSize": payload_size,
            "dscp": dscp
        }
        return self._send_post_request(endpoint=endpoint, headers=headers, json=payload, timeout=timeout)

    def get_ip_connectivity_test_result(self, operation_id, timeout=30):
        endpoint = f'/test/ip-connectivity/{operation_id}'
        headers = {
            "accept": "application/json"
        }
        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)
